import math
import numpy as np
from sklearn.ensemble import HistGradientBoostingClassifier as HC, HistGradientBoostingRegressor as HR

def data(n: int, p: int, nc: int):
    X = np.zeros((n, p)); y = np.zeros(n, dtype=int)
    for i in range(n):
        y[i] = i % nc
        for j in range(p):
            v = (i * 7919 + j * 104729 + i * j * 13 + j * j * 3) % 101
            X[i, j] = (v - 50.0) / 25.0 + (0.8 * y[i] if (j + y[i]) % 2 == 0 else -0.3 * y[i])
        X[i, p - 1] = math.sin(i * 1.7) * 3.0 + 0.01 * i
    return X, y

def close(got, exp: List[float], rtol: float, atol: float = 1e-12) -> bool:
    g = np.asarray(got, dtype=float).ravel()
    if g.size != len(exp):
        print("size mismatch", g.size, len(exp))
        return False
    for i in range(len(exp)):
        if math.isnan(exp[i]) and math.isnan(g[i]):
            continue
        if abs(g[i] - exp[i]) > atol + rtol * abs(exp[i]):
            print("mismatch at", i, g[i], exp[i])
            return False
    return True

def rows_every(X, step: int):
    idx = list(range(0, X.shape[0], step))
    out = np.empty((len(idx), X.shape[1]))
    for t in range(len(idx)):
        for j in range(X.shape[1]):
            out[t, j] = X[idx[t], j]
    return out

