R = 1e-9
A = 1e-12
X, y = data(600, 5, 3)
yr = np.array([math.sin(X[i, 0]) * 2.0 + X[i, 1] * X[i, 2] + 0.1 * (i % 7) for i in range(600)])
yb = np.array([1 if y[i] == 1 else 0 for i in range(600)])
Xt = rows_every(X, 37)
Xn = X.copy()
for i in range(600):
    if i % 7 == 0:
        Xn[i, 1] = math.nan
    if i % 11 == 3:
        Xn[i, 3] = math.nan
Xtn = rows_every(Xn, 37)
sw = np.array([1.0 + (i % 5) * 0.5 for i in range(600)])
Xc = X.copy()
for i in range(600):
    Xc[i, 2] = float((i * 7) % 6) * 2.0 + 1.0
    if i % 13 == 0:
        Xc[i, 2] = math.nan
yc = yr + np.array([1.5 if (Xc[i, 2] == 3.0 or Xc[i, 2] == 9.0) else 0.0 for i in range(600)])
Xtc = rows_every(Xc, 37)

@test
def t_reg_basic():
    r = HR(max_iter=15, random_state=0).fit(X, yr)
    assert close(r.predict(Xt), r_pred, R, A)
    assert r.n_iter_ == 15 and r.train_score_.shape[0] == 0
    assert close(np.array(r._bin_mapper.bin_thresholds_[4]), r_th4, 0.0, 0.0)
    assert close(np.array(r._bin_mapper.bin_thresholds_[0]), r_th0, 0.0, 0.0)
    r16 = HR(max_iter=8, max_bins=16, max_leaf_nodes=8, l2_regularization=0.5, random_state=0).fit(X, yr, sample_weight=sw)
    assert close(r16.predict(Xt), r16_pred, R, A)
    assert close(np.array(r16._bin_mapper.bin_thresholds_[4]), r16_th4, 0.0, 0.0)
    st = List[float]()
    for p in HR(max_iter=4, random_state=0).fit(X, yr).staged_predict(rows_every(Xt, 1)[:3]):
        for v in p:
            st.append(v)
    assert close(np.array(st), r_staged, R, A)

@test
def t_reg_losses():
    m1 = HR(loss="absolute_error", max_iter=10, max_depth=3, random_state=0).fit(X, yr)
    assert close(m1.predict(Xt), r_absolute_error, R, A)
    ye = np.exp(yr / 3.0)
    m2 = HR(loss="poisson", max_iter=10, max_depth=3, random_state=0).fit(X, ye)
    assert close(m2.predict(Xt), r_poisson, R, A)
    m3 = HR(loss="gamma", max_iter=10, max_depth=3, random_state=0).fit(X, ye)
    assert close(m3.predict(Xt), r_gamma, R, A)
    mq = HR(loss="quantile", quantile=0.8, max_iter=10, min_samples_leaf=10, random_state=0).fit(X, yr)
    assert close(mq.predict(Xt), r_quantile, R, A)

@test
def t_reg_features():
    mn = HR(max_iter=10, random_state=0).fit(Xn, yr)
    assert close(mn.predict(Xtn), r_nan, R, A)
    mc = HR(max_iter=10, categorical_features=[2], random_state=0).fit(Xc, yc)
    assert close(mc.predict(Xtc), r_cat, R, A)
    mm = HR(max_iter=10, monotonic_cst=[1, 0, -1, 0, 0], random_state=0).fit(X, yr)
    assert close(mm.predict(Xt), r_mono, R, A)
    mi = HR(max_iter=10, interaction_cst=[[0, 1], [2, 3, 4]], random_state=0).fit(X, yr)
    assert close(mi.predict(Xt), r_ic, R, A)
    mf = HR(max_iter=10, max_features=0.5, random_state=3).fit(X, yr)
    assert close(mf.predict(Xt), r_mf, R, A)

@test
def t_reg_es_warm():
    me = HR(max_iter=200, early_stopping=True, n_iter_no_change=3, random_state=1).fit(X, yr)
    assert me.n_iter_ == r_es_n
    assert close(me.validation_score_, r_es_val, R, A) and close(me.predict(Xt), r_es_pred, R, A)
    me2 = HR(max_iter=200, early_stopping=True, scoring=None, validation_fraction=None, n_iter_no_change=2, tol=1e-3, random_state=1).fit(X, yr)
    assert me2.n_iter_ == r_es2_n and close(me2.train_score_, r_es2_train, R, A)
    w = HR(max_iter=5, warm_start=True, random_state=0).fit(X, yr)
    w.max_iter = 12
    w.fit(X, yr)
    assert w.n_iter_ == 12 and close(w.predict(Xt), r_warm, R, A)

@test
def t_clf():
    c = HC(max_iter=10, random_state=0).fit(X, y)
    assert close(c.predict_proba(Xt), c_proba, R, A)
    cb = HC(max_iter=10, random_state=0, class_weight="balanced").fit(X, yb)
    assert close(cb.predict_proba(Xt), cb_proba, R, A) and close(cb.decision_function(Xt), cb_dec, R, A)
    assert cb.decision_function_1d(Xt).shape[0] == Xt.shape[0]
    ces = HC(max_iter=100, early_stopping=True, n_iter_no_change=2, scoring=None, random_state=2).fit(X, y)
    assert ces.n_iter_ == c_es_n and close(ces.validation_score_, c_es_val, R, A) and close(ces.train_score_, c_es_train, R, A)
    ces2 = HC(max_iter=100, early_stopping=True, n_iter_no_change=3, random_state=5).fit(Xn, yb, sample_weight=sw)
    assert ces2.n_iter_ == c_es2_n and close(ces2.validation_score_, c_es2_val, R, A)
    assert close(ces2.predict_proba(Xtn), c_es2_proba, R, A)
    cc = HC(max_iter=8, categorical_features=[False, False, True, False, False], random_state=0).fit(Xc, y)
    assert close(cc.predict_proba(Xtc), c_cat, R, A)
    cs = List[float]()
    for p in HC(max_iter=3, random_state=0).fit(X, yb).staged_predict_proba(rows_every(Xt, 1)[:4]):
        for i in range(p.shape[0]):
            cs.append(p[i, 1])
    assert close(np.array(cs), c_staged, R, A)
    assert c.score(X, y) > 0.7

t_reg_basic()
t_reg_losses()
t_reg_features()
t_reg_es_warm()
t_clf()
